result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/semver.py", "content": """"Semantic Versioning 2.0.0 parsing, comparison, and npm-style range matching.

Python stdlib only.
"""

from __future__ import annotations

import functools
import re
from typing import List, NamedTuple, Optional, Tuple


class SemverError(ValueError):
    """Raised for invalid version strings or ranges."""


_VERSION_RE = re.compile(
    r"""
    ^
    (?P<major>0|[1-9]\d*)
    \.(?P<minor>0|[1-9]\d*)
    \.(?P<patch>0|[1-9]\d*)
    (?:-(?P<pre>
        [0-9A-Za-z-]+
        (?:\.[0-9A-Za-z-]+)*
    ))?
    (?:\+(?P<build>
        [0-9A-Za-z-]+
        (?:\.[0-9A-Za-z-]+)*
    ))?
    $
    """,
    re.VERBOSE,
)

# A single dot-separated identifier of a prerelease or build section.
_IDENTIFIER_RE = re.compile(r"^[0-9A-Za-z-]+$")
_NUMERIC_IDENTIFIER_RE = re.compile(r"^(?:0|[1-9]\d*)$")


class Version(NamedTuple):
    major: int
    minor: int
    patch: int
    prerelease: Tuple[Tuple[str, Optional[int]], ...]
    build: Tuple[str, ...]

    def __str__(self) -> str:
        s = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            s += "-" + ".".join(str(p) for p in self.prerelease)
        if self.build:
            s += "+" + ".".join(self.build)
        return s


def _parse_identifiers(text: str, section: str) -> tuple:
    parts = text.split(".")
    for part in parts:
        if not part:
            raise SemverError(f"empty identifier in {section} section: {text!r}")
        if not _IDENTIFIER_RE.match(part):
            raise SemverError(f"invalid identifier {part!r} in {section} section")
    if section == "prerelease":
        return tuple((p, int(p)) if _NUMERIC_IDENTIFIER_RE.match(p) else (p, None) for p in parts)
    return tuple(parts)


def parse(version: str) -> Version:
    """Parse a strict SemVer 2.0.0 string into a :class:`Version`."""
    if not isinstance(version, str):
        raise SemverError("version must be a string")
    m = _VERSION_RE.match(version.strip())
    if not m:
        raise SemverError(f"invalid semantic version: {version!r}")
    return Version(
        major=int(m.group("major")),
        minor=int(m.group("minor")),
        patch=int(m.group("patch")),
        prerelease=_parse_identifiers(m.group("pre") or "", "prerelease") if m.group("pre") else (),
        build=_parse_identifiers(m.group("build"), "build") if m.group("build") else (),
    )


def cmp(a, b) -> int:
    """Full SemVer 2.0.0 precedence comparison.

    Returns -1, 0, or 1. Build metadata is ignored. Numeric prerelease
    identifiers compare numerically; numeric < alphanumeric; a larger set of
    identifiers has higher precedence when one is a prefix of the other;
    no prerelease > any prerelease.
    """
    va = parse(a) if isinstance(a, str) else a
    vb = parse(b) if isinstance(b, str) else b

    for x, y in zip(va[:3], vb[:3]):
        if x != y:
            return -1 if x < y else 1

    pa, pb = va.prerelease, vb.prerelease
    if not pa and not pb:
        return 0
    # A version without prerelease has higher precedence.
    if not pa:
        return 1
    if not pb:
        return -1

    for (ia, na), (ib, nb) in zip(pa, pb):
        if ia == ib:
            continue
        # Numeric identifiers are compared numerically.
        if na is not None and nb is not None:
            return -1 if na < nb else 1
        # Numeric identifiers always have lower precedence than alphanumeric.
        if na is not None:
            return -1
        if nb is not None:
            return 1
        return -1 if ia < ib else 1
    # A larger set of prerelease fields has higher precedence.
    return -1 if len(pa) < len(pb) else (1 if len(pa) > len(pb) else 0)


# ---------------------------------------------------------------------------
# Ranges
# ---------------------------------------------------------------------------

_COMPARATOR_RE = re.compile(
    r"""
    ^
    (?P<op>\^|~|>=|<=|>|<|=)?
    (?P<version>.+?)$
    """,
    re.VERBOSE,
)


def _parse_partial(text: str) -> dict:
    """Parse a possibly-partial version like '1', '1.2', '1.2.x', '1.x'."""
    text = text.strip()
    partial = {"major": None, "minor": None, "patch": None, "prerelease": ()}
    if text in ("", "*", "x", "X"):
        return partial
    core = text
    pre = ()
    if "-" in core:
        core, pre_text = core.split("-", 1)
        pre = _parse_identifiers(pre_text, "prerelease")
    parts = core.split(".")
    if len(parts) > 3:
        raise SemverError(f"invalid partial version: {text!r}")
    values = []
    for part in parts:
        if part in ("x", "X", "*"):
            values.append(None)
        elif part.isdigit() and _NUMERIC_IDENTIFIER_RE.match(part):
            values.append(int(part))
        elif part == "":
            raise SemverError(f"invalid partial version: {text!r}")
        else:
            raise SemverError(f"invalid partial version component {part!r}")
    while len(values) < 3:
        values.append(None)
    major, minor, patch = values
    if major is None:
        minor = patch = None
    if minor is None:
        patch = None
    if pre and patch is None:
        raise SemverError(f"prerelease on a partial version without full M.m.p: {text!r}")
    partial.update(major=major, minor=minor, patch=patch, prerelease=pre)
    return partial


def _comparator_fn(op: str, v: Version):
    if op == "<":
        return lambda c: cmp(c, v) < 0
    if op == "<=":
        return lambda c: cmp(c, v) <= 0
    if op == ">":
        return lambda c: cmp(c, v) > 0
    if op == ">=":
        return lambda c: cmp(c, v) >= 0
    if op == "=" or op == "":
        return lambda c: (
            cmp(c, v) == 0 and "".join(map(str, c.build)) == "".join(v.build)
            if v.build
            else cmp(c, v) == 0
        )
    raise SemverError(f"unknown operator: {op}")


def _caret(partial: dict) -> list:
    """Caret range: allow changes that do not modify the leftmost nonzero."""
    if partial["major"] is None:
        return [_comparator_fn(">=", parse("0.0.0"))]
    if partial["major"] > 0 or partial["minor"] is None:
        upper = f"{partial['major'] + 1}.0.0"
    elif partial["minor"] > 0 or partial["patch"] is None:
        upper = f"{partial['major']}.{partial['minor'] + 1}.0"
    else:
        upper = f"{partial['major']}.{partial['minor']}.{partial['patch'] + 1}"
    lower = _full_version_str(partial)
    comps = [_comparator_fn(">=", parse(lower)), _comparator_fn("<", parse(upper))]
    return comps


def _tilde(partial: dict) -> list:
    """Tilde range: allow patch-level changes if minor specified, minor-level otherwise."""
    if partial["major"] is None:
        return [_comparator_fn(">=", parse("0.0.0"))]
    if partial["minor"] is None:
        upper = f"{partial['major'] + 1}.0.0"
        lower = f"{partial['major']}.0.0"
    else:
        upper = f"{partial['major']}.{partial['minor'] + 1}.0"
        lower = _full_version_str(partial)
    return [_comparator_fn(">=", parse(lower)), _comparator_fn("<", parse(upper))]


def _full_version_str(partial: dict) -> str:
    s = f"{partial['major']}.{partial['minor']}.{partial['patch']}"
    if partial["prerelease"]:
        s += "-" + ".".join(str(p) for p in partial["prerelease"])
    return s


def _parse_comparator(token: str):
    m = _COMPARATOR_RE.match(token.strip())
    if not m:
        raise SemverError(f"invalid comparator: {token!r}")
    op = m.group("op") or ""
    partial = _parse_partial(m.group("version"))

    if op == "^":
        return _caret(partial)
    if op == "~":
        return _tilde(partial)

    # Exact / comparator forms.
    if op in ("", "="):
        if partial["patch"] is None:
            # Bare '1' or '1.2' with no operator means an exact-ish range
            # equal to the whole block (npm treats '1.2' as '1.2.x').
            if partial["minor"] is None:
                return [
                    _comparator_fn(">=", parse(f"{partial['major']}.0.0")),
                    _comparator_fn("<", parse(f"{partial['major'] + 1}.0.0")),
                ]
            return [
                _comparator_fn(">=", parse(f"{partial['major']}.{partial['minor']}.0")),
                _comparator_fn("<", parse(f"{partial['major']}.{partial['minor'] + 1}.0")),
            ]
        v = parse(_full_version_str(partial))
        if v.build:
            # Exact match including build metadata is unusual but allowed.
            return [_comparator_fn("=", v)]
        return [_comparator_fn("", v)]

    # >, >=, <, <= with partial versions fill missing parts with zeros.
    filled = _full_version_str(partial) if partial["patch"] is not None else None
    if op in (">", "<=") and partial["patch"] is None:
        # '>1.2' means '>=1.3.0'; '<=1.2' means '<1.3.0'
        if partial["minor"] is None:
            lo = f"{partial['major']}.0.0"
            hi_next = f"{partial['major'] + 1}.0.0"
        else:
            lo = f"{partial['major']}.{partial['minor'] + 1}.0"
            hi_next = lo
        if op == ">":
            return [_comparator_fn(">=", parse(lo))]
        return [_comparator_fn("<", parse(hi_next))]
    if op in (">=", "<") and partial["patch"] is None:
        base = f"{partial['major']}.0.0" if partial["minor"] is None else f"{partial['major']}.{partial['minor']}.0"
        if op == ">=":
            return [_comparator_fn(">=", parse(base))]
        return [_comparator_fn("<", parse(base))]
    return [_comparator_fn(op, parse(filled))]


class Range:
    """An npm-style semver range."""

    def __init__(self, range_spec: str):
        self.raw = range_spec.strip()
        self.alternatives: List[List] = []
        if self.raw == "" or self.raw == "*":
            self.alternatives.append([_comparator_fn(">=", parse("0.0.0"))])
            return
        for alt in self.raw.split("||"):
            alt = alt.strip()
            comparators = []
            tokens = alt.split() if alt else []
            # Handle hyphen ranges 'a - b'
            if len(tokens) == 3 and tokens[1] == "-":
                comparators.extend(_hyphen(tokens[0], tokens[2]))
            else:
                for token in tokens:
                    comparators.extend(_parse_comparator(token))
            if not comparators:
                comparators.append(_comparator_fn(">=", parse("0.0.0")))
            self.alternatives.append(comparators)

    def test(self, version) -> bool:
        v = parse(version) if isinstance(version, str) else version
        for alternative in self.alternatives:
            if all(fn(v) for fn in alternative):
                return True
        return False


def _hyphen(low_text: str, high_text: str) -> list:
    low = _parse_partial(low_text)
    high = _parse_partial(high_text)
    comparators = []
    if low["patch"] is not None:
        comparators.append(_comparator_fn(">=", parse(_full_version_str(low))))
    elif low["minor"] is not None:
        comparators.append(_comparator_fn(">=", parse(f"{low['major']}.{low['minor']}.0")))
    else:
        comparators.append(_comparator_fn(">=", parse(f"{low['major']}.0.0")))
    if high["patch"] is None:
        if high["minor"] is None:
            comparators.append(_comparator_fn("<", parse(f"{high['major'] + 1}.0.0")))
        else:
            comparators.append(_comparator_fn("<", parse(f"{high['major']}.{high['minor'] + 1}.0")))
    else:
        comparators.append(_comparator_fn("<=", parse(_full_version_str(high))))
    return comparators


def valid(version: str) -> bool:
    try:
        parse(version)
        return True
    except SemverError:
        return False


def satisfies(version: str, range_spec: str) -> bool:
    """Return True if *version* satisfies the npm-style *range_spec*."""
    try:
        return Range(range_spec).test(version)
    except SemverError:
        return False
